# parity(wasm_builder/lib/wasm_builder.dart): generated by dev/skeleton.jl from the pinned commit; a filled definition
# replaces its stub in place, and the generator never touches it again.

# wasm_builder.dart, the package's library, which dart2wasm imports as `w`: it re-exports the
# builders, the ir library less the five names its builder declares again (Catch, CatchAll,
# CatchAllRef, CatchRef, TryTableCatch, which `w.` means as the builder's), and the serializer. A
# reference from Dart2Wasm to a WasmBuilder or IR name these directives do not make visible refuses
# the load (src/julia/exports.jl).
@parity "wasm_builder/lib/wasm_builder.dart:5 export" @dart_export "src/builder/builder.dart"

@parity "wasm_builder/lib/wasm_builder.dart:6 export" @dart_export "src/ir/ir.dart" hide Catch CatchAll CatchAllRef CatchRef TryTableCatch

@parity "wasm_builder/lib/wasm_builder.dart:8 export" @dart_export "src/serialize/serialize.dart"
